## solution

#### depth first search

```cpp
#include <vector>
#include <string>
#include <unordered_set>

bool dfs(std::vector<std::vector<char>> grid, std::string target, int r, int c) {
  if (target.length() == 0) {
    return true;
  }

  if (r < 0 || r >= grid.size() || c < 0 || r >= grid[0].size()) {
    return false;
  }

  char currentChar = target[0];
  if (currentChar != grid[r][c]) {
    return false;
  }

  grid[r][c] = '*';

  bool result = dfs(grid, target.substr(1), r - 1, c) || 
    dfs(grid, target.substr(1), r + 1, c) || 
    dfs(grid, target.substr(1), r, c - 1) || 
    dfs(grid, target.substr(1), r, c + 1);

  grid[r][c] = currentChar;

  return result;
}

bool stringSearch(std::vector<std::vector<char>> grid, std::string target) {
  for (int i = 0; i < grid.size(); i += 1) {
    for (int j = 0; j < grid.size(); j += 1) {
      if (dfs(grid, target, i, j)) {
        return true;
      }
    }
  }
  return false;
}
```

- r = # grid rows
- c = # grid columns
- Time: O(3^(r*c))
- Space: O(r*c)
